// ---- palette ----------------------------------------------------------------------------------------------------
export const WHITE_CONCRETE = "white_concrete"; // white body: canopy fascia, shop walls, stall stripes
export const SMOOTH_QUARTZ = "smooth_quartz"; // canopy soffit, columns, shop body
